import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { GoogleOAuthProvider } from '@react-oauth/google';
import './App.css';

// Import components
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';
import MoodTracker from './components/MoodTracker';

// Import pages
import Home from './pages/Home';
import Login from './pages/Login1';
import Signup from './pages/Signup';
import Clinics from './pages/Clinics';
import ClinicDetail from './pages/ClinicDetail';
import Articles from './pages/Articles';
import ArticleDetail from './pages/ArticleDetail';
import Journals from './pages/Journals';
import JournalDetail from './pages/JournalDetail';
import MyProfile from './pages/MyProfile';
import UserProfile from './pages/UserProfile';

function App() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');
    if (token && userData) {
      setUser(JSON.parse(userData));
    }
  }, []);

  const handleLogin = (userData, token) => {
    localStorage.setItem('token', token);
    localStorage.setItem('user', JSON.stringify(userData));
    setUser(userData);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  return (
    <GoogleOAuthProvider clientId={process.env.REACT_APP_GOOGLE_CLIENT_ID || "dummy-client-id"}>
      <Router>
        <div className="App">
          <Navbar user={user} onLogout={handleLogout} />
          
          {user && <MoodTracker />}
          
          <Routes>
            <Route path="/" element={<Home user={user} />} />
            <Route path="/login" element={<Login onLogin={handleLogin} />} />
            <Route path="/signup" element={<Signup onLogin={handleLogin} />} />
            <Route path="/clinics" element={<Clinics />} />
            <Route path="/clinics/:id" element={<ClinicDetail user={user} />} />
            <Route path="/articles" element={<Articles user={user} />} />
            <Route path="/articles/:id" element={<ArticleDetail user={user} />} />
            <Route path="/journals" element={<Journals user={user} />} />
            <Route path="/users/:id" element={<UserProfile />} />
            <Route 
              path="/profile" 
              element={
                <ProtectedRoute user={user}>
                  <MyProfile user={user} />
                </ProtectedRoute>
              } 
            />
          </Routes>
        </div>
      </Router>
    </GoogleOAuthProvider>
  );
}

export default App;
